interface.definition:
a!localVariables(
  local!newDateIndex: wherecontains(
    tointeger(null),
    tointeger(index(
      ri!officeVisitDates,
      "officeVisitDateId",
      {}
    ))
  ),
  local!inactiveDateIndex: wherecontains(
    toboolean(0),
    toboolean(index(
      ri!officeVisitDates,
      "isActive",
      {}
    ))
  ),
  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: "Manage Office Visit Dates",
    instructions: "Manage the office visit date choices the candidates will be able to choose from.",
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            width: "MEDIUM",
            contents: {
              #"SYSTEM_SYSRULES_gridLayout"(
                labelPosition: "COLLAPSED",
                headerCells: {
                  #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Active Dates"),
                  #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(align: "CENTER")
                },
                columnConfigs: {
                  #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE"),
                  #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "ICON")
                },
                rows: #"SYSTEM_SYSRULES_forEach"(
                  items: ri!officeVisitDates,
                  expression: {
                    #"SYSTEM_SYSRULES_gridRowLayout"(
                      contents: {
                        if(
                          a!isNullOrEmpty(index(fv!item,"officeVisitDateId",null)),
                          #"SYSTEM_SYSRULES_dateField"(
                            label: "New Date",
                            value: index(fv!item,"officeVisitDate",null),
                            saveInto: fv!item.officeVisitDate,
                            required: true
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: text(todate(index(fv!item,"officeVisitDate","")),"dddd, MMMM d, yyyy")
                            )
                          )
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          align: "CENTER",
                          value: if(
                            a!isNullOrEmpty(index(fv!item,"officeVisitDateId",null)),
                            #"SYSTEM_SYSRULES_richTextIcon"(
                              icon: "close",
                              color: "NEGATIVE",
                              link: #"SYSTEM_SYSRULES_dynamicLink"(
                                saveInto: {
                                  a!save(ri!officeVisitDates,remove(ri!officeVisitDates,fv!index))
                                }
                              ),
                              linkStyle: "STANDALONE"
                            ),
                            #"SYSTEM_SYSRULES_richTextIcon"(
                              icon: if(
                                index(fv!item,"isActive",false),
                                "toggle-on",
                                "toggle-off"
                              ),
                              size: "MEDIUM_PLUS",
                              color: if(
                                index(fv!item,"isActive",false),
                                "POSITIVE",
                                "SECONDARY"
                              ),
                              link: #"SYSTEM_SYSRULES_dynamicLink"(
                                value: not(index(fv!item,"isActive",false)),
                                saveInto: {
                                  a!save(fv!item.isActive,not(fv!item.isActive))
                                }
                              ),
                              linkStyle: "STANDALONE"
                            )
                          )
                        )
                      }
                    )
                  }
                ),
                addRowLink: #"SYSTEM_SYSRULES_dynamicLink"(
                  label: "Add Date",
                  saveInto: {
                    a!save(
                      ri!officeVisitDates,
                      append(
                        ri!officeVisitDates,
                        'type!{urn:com:appian:types:CAW}CAW_RefOfficeVisitDates'()
                      )
                    )
                  }
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"()
        }
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: #"SYSTEM_SYSRULES_ButtonWidget"(
        label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
        style: "PRIMARY",
        submit: true,
        validate: true,
        value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
        saveInto: {
          {
            a!save(ri!buttonClicked, save!value)
          },
          {
            a!save(ri!officeVisitDates[local!newDateIndex].isActive, 1),
            a!save(ri!officeVisitDates[local!newDateIndex].createdBy, loggedInUser()),
            a!save(ri!officeVisitDates[local!newDateIndex].createdDateTime, now()),
            a!save(ri!officeVisitDates[local!newDateIndex].modifiedBy, loggedInUser()),
            a!save(ri!officeVisitDates[local!newDateIndex].modifiedDateTime, now()),
            a!save(ri!officeVisitDates[local!inactiveDateIndex].modifiedBy, loggedInUser()),
            a!save(ri!officeVisitDates[local!inactiveDateIndex].modifiedDateTime, now())
          }
        }
      ),
      secondaryButtons: #"SYSTEM_SYSRULES_ButtonWidget"(
        label: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3602779",
        style: "SECONDARY",
        submit: true,
        validate: false,
        value: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3602779",
        saveInto: {
          a!save(ri!buttonClicked, save!value)
        }
      )
    )
  )
)
